//! The embedded model: `weights.bin` (generated by
//! `scripts/extract_rnnoise_weights.py` from xiph/rnnoise's rnnoise_data.c,
//! model 0b50c45) parsed once into leaked static slices.

use std::collections::HashMap;
use std::sync::OnceLock;

/// One `LinearLayer`'s weights (the float compute path).
pub(crate) struct Layer {
    pub nb_inputs: usize,
    pub nb_outputs: usize,
    /// Input-major (`weights[j * nb_outputs + i]`).
    pub weights: &'static [f32],
    pub bias: &'static [f32],
    /// Block-sparse row groups (`8x4` blocks) when present.
    pub index: Option<&'static [i32]>,
    /// The recurrent diagonal term (GRU recurrent layers only).
    pub diag: Option<&'static [f32]>,
}

pub(crate) struct Model {
    pub conv1: Layer,
    pub conv2: Layer,
    pub gru1_input: Layer,
    pub gru1_recurrent: Layer,
    pub gru2_input: Layer,
    pub gru2_recurrent: Layer,
    pub gru3_input: Layer,
    pub gru3_recurrent: Layer,
    pub dense_out: Layer,
    pub vad_dense: Layer,
}

/// `include_bytes!` of the extracted float model (about 4.4 MB).
static WEIGHTS_BYTES: &[u8] = include_bytes!("weights.bin");

fn leak_f32(values: Vec<f32>) -> &'static [f32] {
    Box::leak(values.into_boxed_slice())
}

fn leak_i32(values: Vec<i32>) -> &'static [i32] {
    Box::leak(values.into_boxed_slice())
}

/// Parses the container: `"RNDW" | u32 version | u32 count`, then per array
/// `u8 name_len | name | u8 dtype (0 = f32, 1 = i32) | u32 count | payload`.
fn parse(bytes: &'static [u8]) -> Option<(HashMap<String, &'static [f32]>, HashMap<String, &'static [i32]>)> {
    if bytes.len() < 12 || &bytes[..4] != b"RNDW" {
        return None;
    }
    let read_u32 = |at: usize| -> Option<u32> {
        match bytes.get(at..at + 4) {
            Some(value) => {
                let array: [u8; 4] = value.try_into().ok()?;
                Some(u32::from_le_bytes(array))
            }
            None => None,
        }
    };
    let count = read_u32(8)? as usize;
    let mut at = 12usize;
    let mut float = HashMap::new();
    let mut int = HashMap::new();
    for _ in 0..count {
        let name_len = *bytes.get(at)? as usize;
        at += 1;
        let name = bytes.get(at..at + name_len)?;
        let name = std::str::from_utf8(name).ok()?.to_owned();
        at += name_len;
        let dtype = *bytes.get(at)?;
        at += 1;
        let len = read_u32(at)? as usize;
        at += 4;
        let payload = bytes.get(at..at + len * 4)?;
        at += len * 4;
        match dtype {
            0 => {
                let values = payload
                    .chunks_exact(4)
                    .map(|chunk| f32::from_le_bytes(chunk.try_into().unwrap()))
                    .collect();
                float.insert(name, leak_f32(values));
            }
            1 => {
                let values = payload
                    .chunks_exact(4)
                    .map(|chunk| i32::from_le_bytes(chunk.try_into().unwrap()))
                    .collect();
                int.insert(name, leak_i32(values));
            }
            _ => return None,
        }
    }
    Some((float, int))
}

fn blob() -> Option<&'static (HashMap<String, &'static [f32]>, HashMap<String, &'static [i32]>)> {
    static BLOB: OnceLock<Option<(HashMap<String, &'static [f32]>, HashMap<String, &'static [i32]>)>> =
        OnceLock::new();
    BLOB.get_or_init(|| parse(WEIGHTS_BYTES)).as_ref()
}

fn float(name: &str) -> Option<&'static [f32]> {
    blob()?.0.get(name).copied()
}

fn int(name: &str) -> Option<&'static [i32]> {
    blob()?.1.get(name).copied()
}

fn layer(
    bias: &str,
    weights: &str,
    index: Option<&str>,
    diag: Option<&str>,
    nb_inputs: usize,
    nb_outputs: usize,
) -> Option<Layer> {
    Some(Layer {
        nb_inputs,
        nb_outputs,
        weights: float(weights)?,
        bias: float(bias)?,
        index: index.and_then(int),
        diag: diag.and_then(float),
    })
}

/// The complete model, or `None` if the embedded blob failed validation.
pub(crate) fn model() -> Option<&'static Model> {
    static MODEL: OnceLock<Option<Model>> = OnceLock::new();
    MODEL
        .get_or_init(|| {
            Some(Model {
                conv1: layer("conv1_bias", "conv1_weights_float", None, None, 195, 128)?,
                conv2: layer("conv2_bias", "conv2_weights_float", None, None, 384, 384)?,
                gru1_input: layer("gru1_input_bias", "gru1_input_weights_float", Some("gru1_input_weights_idx"), None, 384, 1152)?,
                gru1_recurrent: layer("gru1_recurrent_bias", "gru1_recurrent_weights_float", Some("gru1_recurrent_weights_idx"), Some("gru1_recurrent_weights_diag"), 384, 1152)?,
                gru2_input: layer("gru2_input_bias", "gru2_input_weights_float", Some("gru2_input_weights_idx"), None, 384, 1152)?,
                gru2_recurrent: layer("gru2_recurrent_bias", "gru2_recurrent_weights_float", Some("gru2_recurrent_weights_idx"), Some("gru2_recurrent_weights_diag"), 384, 1152)?,
                gru3_input: layer("gru3_input_bias", "gru3_input_weights_float", Some("gru3_input_weights_idx"), None, 384, 1152)?,
                gru3_recurrent: layer("gru3_recurrent_bias", "gru3_recurrent_weights_float", Some("gru3_recurrent_weights_idx"), Some("gru3_recurrent_weights_diag"), 384, 1152)?,
                dense_out: layer("dense_out_bias", "dense_out_weights_float", None, None, 384, 32)?,
                vad_dense: layer("vad_dense_bias", "vad_dense_weights_float", None, None, 384, 1)?,
            })
        })
        .as_ref()
}
